CREATE TABLE documento (id INTEGER PRIMARY KEY, tipo TEXT, numero TEXT, cliente TEXT, creado TEXT);
CREATE TABLE version (doc_id INTEGER, n INTEGER, archivo_sha TEXT, estado TEXT, autor TEXT, fecha TEXT,
                      PRIMARY KEY (doc_id, n));

-- La versión vigente de cada documento es la de mayor número:
SELECT d.tipo, d.numero, v.n AS version, v.estado
FROM documento d JOIN version v ON v.doc_id = d.id
WHERE v.n = (SELECT MAX(n) FROM version WHERE doc_id = d.id);

const ROLES = { ana: "operador", beto: "jefe", carla: "gerencia" };   // personas inventadas
const UMBRAL = 500;                                                  // USD, inventado
const TRANSICIONES = {
  borrador:          { enviar: "pendiente", anular: "anulado" },
  pendiente:         { aprobar: "aprobado", rechazar: "rechazado", escalar: "pendienteGerencia" },
  pendienteGerencia: { aprobar: "aprobado", rechazar: "rechazado" },
  aprobado: {}, rechazado: {}, anulado: {},
};
function aplicar(s, accion, quien, hora) {
  const destino = (TRANSICIONES[s.estado] || {})[accion];
  if (!destino) return `no: «${accion}» no existe desde «${s.estado}»`;
  const resuelve = accion === "aprobar" || accion === "rechazar" || accion === "escalar";
  if (resuelve && quien === s.autor) return "no: quien creó la solicitud no puede resolverla";
  if (resuelve && s.estado === "pendiente" && !["jefe", "gerencia"].includes(ROLES[quien])) return "no: falta el rol de jefe";
  if (resuelve && s.estado === "pendienteGerencia" && ROLES[quien] !== "gerencia") return "no: este paso es de gerencia";
  if (accion === "aprobar" && s.estado === "pendiente" && s.monto > UMBRAL) return `no: pasa de USD ${UMBRAL}, hay que escalar`;
  s.historial.push(`${hora} ${quien}: ${s.estado} -> ${destino}`);
  s.estado = destino; return "ok";
}
const s = { id: "NC-7", autor: "ana", monto: 820, estado: "borrador", historial: [] };
const pasos = [["enviar","ana","09:00"],["aprobar","ana","09:05"],["aprobar","beto","09:10"],["escalar","beto","09:12"],
               ["aprobar","beto","09:20"],["aprobar","carla","10:02"],["rechazar","carla","10:03"]];
for (const [a, q, h] of pasos) console.log(h, q.padEnd(5), a.padEnd(8), "->", aplicar(s, a, q, h));
console.log("estado final:", s.estado);
console.log(s.historial.join("\n"));
